syntax:
void object_init(struct Object *obj); // Constructor-like function
void object_destroy(struct Object *obj); // Destructor-like function

// Usage pattern:
struct Object obj;
object_init(&obj);
// ... use obj ...
object_destroy(&obj);

code_example:
struct Object {
    int *data;
};

void object_init(struct Object *obj) {
    obj->data = malloc(sizeof(int) * 10);
    // Initialize data...
}

void object_destroy(struct Object *obj) {
    free(obj->data);
    obj->data = NULL;
}

int main() {
    struct Object obj;
    object_init(&obj);
    // ... use obj ...
    object_destroy(&obj);
    return 0;
}
